from typing import List, Tuple
import re
import binascii

def extract_wx_commands(content: str) -> List[Tuple[str, str]]:
    """Extract all wx commands and their target locations."""
    wx_pattern = r'wx ([0-9a-f]+)(?:@(loc\.[^;\s]+))?'
    matches = re.finditer(wx_pattern, content)
    return [(m.group(1), m.group(2) if m.group(2) else '') for m in matches]

def decode_hex_string(hex_str: str) -> str:
    """Decode a hex string to ASCII, handling errors gracefully."""
    try:
        return binascii.unhexlify(hex_str).decode('ascii', errors='replace')
    except:
        return f"(decode error for {hex_str})"

def main():
    with open('/home/ctfplayer/ctf_files/welcome2.r2', 'r') as f:
        content = f.read()

    # Extract location definitions
    loc_defs = {}
    for line in content.split('\n'):
        if line.startswith('f loc.'):
            name, addr = line.split(' = ')
            loc_defs[name.split('.')[-1]] = int(addr, 16)

    print("Memory locations:")
    for name, addr in loc_defs.items():
        print(f"{name}: 0x{addr:x}")

    # Extract and analyze wx commands
    wx_commands = extract_wx_commands(content)

    print("\nAnalyzing write operations:")
    for hex_data, location in wx_commands:
        decoded = decode_hex_string(hex_data)
        if 'flag' in decoded.lower() or 'hash' in decoded.lower():
            print(f"\nImportant operation:")
            print(f"Location: {location}")
            print(f"Hex: {hex_data}")
            print(f"Decoded: {decoded}")

    # Extract hit markers
    hit_markers = {}
    for line in content.split('\n'):
        if line.startswith('f hit'):
            name, value = line.split(' = ')
            hit_markers[name.split()[1]] = int(value)

    print("\nHit markers sequence:")
    for marker, offset in sorted(hit_markers.items(), key=lambda x: int(x[1])):
        print(f"{marker}: offset {offset}")

    # Look for patterns in operations around flag references
    flag_ops = []
    for line in content.split('\n'):
        if 'loc.flag' in line:
            flag_ops.append(line)

    print("\nFlag-related operations:")
    for op in flag_ops:
        print(op)

if __name__ == '__main__':
