#!/usr/bin/env python3
import re
from typing import List, Tuple, Dict

def parse_r2_script(content: str) -> Dict:
    results = {
        'flag_ops': [],
        'hash_ops': [],
        'tmp_files': set(),
        'hit_markers': [],
        'wx_commands': []
    }

    lines = content.split('\n')
    for line in lines:
        # Parse flag operations
        if 'loc.flag' in line:
            if match := re.search(r'@loc\.flag\+([0-9]+)', line):
                offset = int(match.group(1))
                results['flag_ops'].append((offset, line))

        # Parse hash operations
        if 'loc.hash' in line:
            if match := re.search(r'@loc\.hash\+([0-9]+)', line):
                offset = int(match.group(1))
                results['hash_ops'].append((offset, line))

        # Parse temporary files
        if '/tmp/' in line:
            if match := re.search(r'/tmp/([^;\s]+)', line):
                results['tmp_files'].add(match.group(1))

        # Parse hit markers
        if line.startswith('f hit'):
            if match := re.search(r'f (hit[0-9]+) = ([0-9]+)', line):
                results['hit_markers'].append((match.group(1), int(match.group(2))))

        # Parse wx commands
        if line.startswith('wx '):
            if match := re.search(r'wx ([0-9a-f]+)(?:@([^;\s]+))?', line):
                hex_data = match.group(1)
                location = match.group(2) if match.group(2) else ''
                results['wx_commands'].append((hex_data, location))

    return results

def analyze_operations(results: Dict) -> str:
    summary = []
    summary.append("=== Analysis Summary ===\n")

    # Analyze flag operations
    summary.append("Flag Operations (sorted by offset):")
    flag_ops = sorted(results['flag_ops'], key=lambda x: x[0])
    for offset, op in flag_ops[:10]:  # Show first 10
        summary.append(f"  offset {offset:3d}: {op}")
    if len(flag_ops) > 10:
        summary.append(f"  ... and {len(flag_ops)-10} more operations")

    # Analyze hash operations pattern
    summary.append("\nHash Operation Pattern:")
    hash_offsets = sorted(set(offset for offset, _ in results['hash_ops']))
    summary.append(f"  Found {len(hash_offsets)} unique hash offsets")
    summary.append(f"  First few offsets: {hash_offsets[:5]}")

    # Analyze temporary files
    summary.append("\nTemporary Files Used:")
    for tmp in sorted(results['tmp_files']):
        summary.append(f"  /tmp/{tmp}")

    # Analyze wx commands that might contain important data
    summary.append("\nInteresting wx Commands:")
    for hex_data, location in results['wx_commands']:
        try:
            ascii_data = bytes.fromhex(hex_data).decode('ascii', errors='replace')
            if any(x in ascii_data.lower() for x in ['flag', 'hash', 'key', 'pwd']):
                summary.append(f"  {hex_data} -> {ascii_data} @ {location}")
        except:
            continue

    # Analyze execution flow through hit markers
    summary.append("\nExecution Flow:")
    hit_markers = sorted(results['hit_markers'], key=lambda x: x[1])
    marker_count = len(hit_markers)
    summary.append(f"  Found {marker_count} hit markers")
    summary.append(f"  First marker: {hit_markers[0]}")
    summary.append(f"  Last marker: {hit_markers[-1]}")

    return "\n".join(summary)

def main():
    with open('/home/ctfplayer/ctf_files/welcome2.r2', 'r') as f:
        content = f.read()

    results = parse_r2_script(content)
    analysis = analyze_operations(results)
    print(analysis)

if __name__ == '__main__':
    main()

